create table public.quiz_questions (
  quiz_id text not null,
  id text not null,
  section_id text not null,
  group_id text not null,
  position integer not null,
  document jsonb not null,
  version integer default 1 not null,
  constraint quiz_questions_pkey PRIMARY KEY (quiz_id, id),
  constraint quiz_questions_quiz_id_fkey FOREIGN KEY (quiz_id) REFERENCES public.quizzes(id) ON DELETE CASCADE,
  constraint quiz_questions_document_check CHECK ((jsonb_typeof(document) = 'object'::text)),
  constraint quiz_questions_id_check CHECK ((id ~ '^[A-Za-z0-9][A-Za-z0-9._+-]{0,63}$'::text)),
  constraint quiz_questions_position_check CHECK (("position" >= 0)),
  constraint quiz_questions_version_check CHECK ((version >= 1))
);

CREATE INDEX quiz_questions_order ON public.quiz_questions USING btree (quiz_id, section_id, "position");

alter table public.quiz_questions enable row level security;

grant delete, insert, maintain, references, select, trigger, truncate, update on table public.quiz_questions to service_role;
